      if (f === 'team' && st === 'hs' && lv >= 3 && life.flags.club !== '野球部') t = lv === 4 ? 'インターハイで入賞' : 'インターハイに出場';
      const who = st === 'elem' ? '' : life.flags.club && fields.has(clubField(life.flags.club)) && clubField(life.flags.club) === f ? `${life.flags.club}で、` : '';
      life.awards = (life.awards || []).concat([{ age: a, f, lv, t }]);
