  // 友だちの名前：人生ごとに、学校・職場で出会った友だちを10人ほど持っておき、毎回ちがう人から連絡が来るようにする
  function friendName(life, bestP = 0.25) {
    const r = life.r, c = life.cast = life.cast || {}, a = life.age;
    if (c.best && c.best.alive !== false && c.best.name && r.chance(bestP)) return c.best.name;
    c.fpool = c.fpool || [];
    const stage = a < 13 ? '小学校' : a < 16 ? '中学' : a < 19 ? '高校' : a < 23 ? '大学・専門' : '職場・地元';
    const here = c.fpool.filter((x) => x.st === stage || (a >= 23 && x.st !== '小学校'));
    if (here.length < (a < 23 ? 4 : 7)) { const sx = r.chance(0.65) ? life.sex : (life.sex === 'M' ? 'F' : 'M'); const g = pickGiven(r, sx, a < 30 ? 'peer' : 'parent'); if (!c.fpool.some((x) => x.n === g.k) && (!c.best || c.best.name !== g.k)) { c.fpool.push({ n: g.k, st: stage }); return g.k; } }
    const pool = here.length ? here : c.fpool;
    return pool.length ? r.pick(pool).n : pickGiven(r, life.sex, 'peer').k;
  }

