  // 文面の書き分け「A（B）」を、その人生の性別や関係に合わせて片方に決める
  const fixPhone = (l, q, P) => (P ? Object.assign({}, P, { from: fixAlt(l, q, P.from), msgs: (P.msgs || []).map((m) => fixAlt(l, q, m)), mine: P.mine && P.mine.map((m) => fixAlt(l, q, m)) }) : P);
  function fixAlt(l, q, str) {
    if (typeof str !== 'string' || str.indexOf('（') < 0) return str;
    const M = l.sex === 'M', sp = l.spouse && l.spouse.sex, k = ((q && q.p) || 0) % 2 === 0;
    return str
      .replace(/ひいおじいちゃん（ひいおばあちゃん）/g, M ? 'ひいおじいちゃん' : 'ひいおばあちゃん')
      .replace(/おじいちゃん（おばあちゃん）/g, M ? 'おじいちゃん' : 'おばあちゃん').replace(/おばあちゃん（おじいちゃん）/g, M ? 'おばあちゃん' : 'おじいちゃん')
      .replace(/じいじ（ばあば）/g, M ? 'じいじ' : 'ばあば')
      .replace(/お父さん（お母さん）/g, M ? 'お父さん' : 'お母さん').replace(/お母さん（お父さん）/g, M ? 'お父さん' : 'お母さん')
      .replace(/パパ（ママ）/g, M ? 'パパ' : 'ママ').replace(/母の日（父の日）/g, M ? '父の日' : '母の日')
      .replace(/お嫁さん（お婿さん）/g, M ? 'お婿さん' : 'お嫁さん')
      .replace(/息子（娘）/g, sp === 'F' ? '娘' : '息子').replace(/奥さま（ご主人）/g, M ? '奥さま' : 'ご主人')
      .replace(/女（男）/g, M ? '男' : '女').replace(/花嫁（花婿）/g, k ? '花嫁' : '花婿')
      .replace(/私（俺）/g, k ? '私' : '俺').replace(/わたし（ぼく）/g, k ? 'わたし' : 'ぼく').replace(/私（僕）/g, k ? '私' : '僕')
      .replace(/彼氏（彼女）/g, k ? '彼氏' : '彼女').replace(/妹（弟）/g, k ? '妹' : '弟').replace(/お義母さん（お義父さん）/g, k ? 'お義母さん' : 'お義父さん')
      .replace(/振袖・スーツ姿/g, k ? '振袖姿' : 'スーツ姿').replace(/お父さん（お母さん）が/g, k ? 'お父さんが' : 'お母さんが');
  }
