  const fufuStage = (l) => (l.age < 35 ? 'y' : l.age < 60 ? 'm' : 'o');
  function fufuPat(l, q) {
    const st = fufuStage(l), kids = (l.kids || []).some((k) => k.alive), strain = l.flags.marriageStrain || 0;
    const list = FUFU2.filter((x) => (!x.st || x.st === st) && (!x.kids || kids));
    const w = (x) => (x.t === 'kenka' ? 1 + strain * 0.6 : x.t === 'love' || x.t === 'surprise' ? Math.max(0.3, 1.2 - strain * 0.3) : 1);
    const tot = list.reduce((t, x) => t + w(x), 0); let k = (((q && q.p) || 0) % 1000) / 1000 * tot;
    for (const x of list) { k -= w(x); if (k <= 0) return x; }
    return list[0];
  }
  const ms = (l, v) => { l.flags.marriageStrain = Math.max(0, (l.flags.marriageStrain || 0) + v); };
