    const lg = Math.log10(life.sns + 10); // 大きいアカウントほど伸びにくい
    let g = r.norm(active ? 0.38 - 0.075 * lg : 0.03 - 0.012 * lg, active ? 0.35 : 0.12) + 0.03 * E;
    // バズ
