    if (viral) { g += r.logn(0.9, 0.55) / (1 + Math.max(0, lg - 3) * 0.6); }
    const before = life.sns;
    life.sns = Math.max(0, Math.round(life.sns * Math.exp(g) + (active ? r.int(0, 50) : 0)));
    if (viral && life.sns - before > 1000) log(life, 'hobby', `投稿した${r.pick(['動画', '写真', 'イラスト', 'つぶやき'])}がバズって、フォロワーが${fmtNum(before)}人から${fmtNum(life.sns)}人に増えました。`, 'good');
    for (const [th, msg] of [[1e4, 'フォロワーが1万人を超えました。'], [1e5, 'フォロワーが10万人を超え、企業からPR案件が届くようになりました。'], [1e6, 'フォロワーが100万人を突破しました。街で声をかけられることも増えました。'], [1e7, 'フォロワーが1,000万人を超え、日本有数のインフルエンサーになりました。'], [1e8, 'フォロワーが1億人を超えました。世界でもトップクラスの発信者です。']]) {
      if (before < th && life.sns >= th) { log(life, 'hobby', msg, 'good', th >= 1e5 ? 'フォロワー10万人以上のアカウントを持つのは、SNS利用者のごく一部です。' : undefined); life.stats.happy += 4; }
    }
