    if (life.lifestyle && life.lifestyle.snow && a >= 5 && r.chance(0.04)) say(a < 15 ? '大雪の日、家族総出で雪かきをしました。かまくらを作りました。' : '今年も雪かきの季節が来ました。腰にこたえます。', 'neutral');
    if (life.pref !== life.birthPref && a >= 20 && r.chance(0.08)) say(r.pick([`お正月に${life.birthPref}の実家へ帰省しました。${life.fam.mother.alive ? '母の作った雑煮を食べました。' : ''}`, `${life.birthCity}に帰ると、駅前の店がいくつもなくなっていました。`]), 'neutral');
