    M['被服・日用品'] = 1.0 + 0.8 * (adults - 1) + 0.5 * kids.length;
    M['教養娯楽'] = 1.4 + 0.8 * (adults - 1) + 0.4 * kids.length;
    M['交際費・保険など'] = (2.2 + 2.0 * (adults - 1)) * (a >= 70 ? 0.8 : 1); // 高齢期は生命保険料が減る
    M['臨時の出費'] = a >= 65 ? 0.5 * adults : 1.2 + 0.8 * (adults - 1) + 0.3 * kids.length; // 冠婚葬祭・家電・帰省・家族旅行など
