    let T;
    if (y < 1970) T = fam ? pk([['公団住宅', '2DK', 1], ['長屋', '2K', 0.75], ['木造の借家', '3K', 0.85], ['文化住宅', '2K', 0.7]]) : pk([['下宿', '4.5畳', 0.55], ['木造アパート（風呂なし・共同トイレ）', '6畳', 0.6], ['間借り', '6畳', 0.5], ['会社の寮', '6畳', 0.4]]);
    else if (fam) {
      const big = kids >= 2 ? '3LDK' : kids === 1 ? pk(['2LDK', '3DK']) : pk(['1LDK', '2LDK', '2DK']);
      T = pk([['マンション', big, 1], ['マンション', big, 1], ['団地', kids >= 1 ? '3DK' : '2DK', 0.72], ['テラスハウス', big, 0.95]].concat(rural ? [['一戸建て（賃貸）', '4DK', 0.95], ['古民家', '5DK', 0.6]] : [['タワーマンション', big, y >= 2000 ? 1.5 : 1.2], ['一戸建て（賃貸）', '3LDK', 1.1]]).concat(l.job && /大企業|公務員/.test((l.job.tier || '') + (l.job.kind || '')) ? [['社宅', big, 0.5]] : []));
    } else T = pk([['アパート', pk(['1K', '1K', 'ワンルーム']), 0.92], ['マンション', pk(['1K', '1DK', '1LDK']), 1.08], ['アパート', '1DK', 1], ['デザイナーズマンション', '1LDK', 1.3]].concat(young && metro && y >= 2005 ? [['シェアハウス', '個室', 0.7]] : []).concat(rural ? [['古い一軒家', '2DK', 0.65]] : []).concat(y < 1995 ? [['木造アパート（風呂なし）', '6畳', 0.55]] : []));
    const [type, lay, base] = T;
    const old = type === '古民家' ? 60 + Math.floor(rp() * 60) : /新築/.test(type) ? 0 : rp() < 0.12 ? 0 : Math.floor(rp() * rp() * 45) + 1;
    const floor = /一戸建て|一軒家|古民家|長屋|テラス|借家|文化住宅|間借り|下宿/.test(type) ? null : type === 'タワーマンション' ? 10 + Math.floor(rp() * 35) : 1 + Math.floor(rp() * (type === 'アパート' || /木造/.test(type) ? 2 : 10));
    const m2 = Math.round(({ 'ワンルーム': 20, '1K': 24, '1DK': 30, '1LDK': 40, '2K': 32, '2DK': 45, '2LDK': 58, '3DK': 60, '3K': 48, '3LDK': 72, '4DK': 85, '5DK': 120, '個室': 12, '6畳': 12, '4.5畳': 9 }[lay] || 30) * (0.88 + rp() * 0.3));
    const walk = rural ? 10 + Math.floor(rp() * 30) : 2 + Math.floor(rp() * 18);
