    const feat = (cond, t, m, eff) => cond && F.push({ t, m, eff });
    const pool = [[1, '南向き・日当たり良好', 1.03, 'sun'], [1, '角部屋', 1.03], [y >= 1990, 'ペット可', 1.04, 'pet'], [y >= 1995 && !/アパート|木造|古|団地/.test(type), 'オートロック', 1.03], [y >= 2005, '宅配ボックス', 1.01], [lay !== '個室', 'ロフト付き', 1.02], [1, '商店街がすぐそば', 1.0, 'shop'], [1, '公園の隣', 1.01, 'park'], [1, '線路沿い（電車の音が聞こえる）', 0.92, 'noise'], [1, '坂の上', 0.95], [1, '大家さんが同じ建物', 0.98, 'oya'], [fam, '庭付き', 1.05, 'niwa'], [fam || rural, '駐車場つき', 1.02], [floor >= 8, '眺望良好', 1.06, 'view'], [1, '和室あり', 0.98, 'wa'], [y >= 1980, 'ウォークインクローゼット', 1.03], [old >= 30, 'リノベーション済み', 1.08], [1, '近くにコンビニ', 1.01, 'konbini']];
    for (let t = 0; t < 2 + (rp() < 0.4 ? 1 : 0); t++) { const c = pool.filter((p) => p[0] && !F.some((f) => f.t === p[1])); const p = c[Math.floor(rp() * c.length)]; if (p) feat(true, p[1], p[2], p[3]); }
    if (y >= 1990 && !/社宅|寮/.test(type) && rp() < 0.035) F.push({ t: '告知事項あり（いわゆる事故物件）', m: 0.6, eff: 'jiko' });
    let mult = base * (old === 0 ? 1.15 : old >= 35 ? 0.78 : old >= 20 ? 0.9 : 1) * (walk <= 5 ? 1.06 : walk >= 15 ? 0.92 : 1);
