    return { type: old === 0 && !/古/.test(type) ? `新築${type}` : type, lay, old, floor, m2, walk, feats: F.map((f) => f.t), effs: F.map((f) => f.eff).filter(Boolean), mult: Math.max(0.35, Math.min(1.9, mult)) };
