        { label: '長電話で近況を話す', say: '元気だよ。そっちはどう？ じつは最近さ…', hint: '', w: 30, apply: (l) => { l.stats.happy += 2; l.flags.oyaBond = (l.flags.oyaBond || 0) + 0.5; return '1時間ほど話しこみました。電話を切ると、少し心が軽くなっていました。'; } },
        { label: '「忙しいから、また今度」', say: 'ごめん、いま忙しくて。また今度ね。', hint: '', w: 20, apply: (l) => { l.flags.oyaBond = (l.flags.oyaBond || 0) - 0.5; return '用件だけ聞いて、電話を切りました。'; } },
        { label: '出ない', decline: true, hint: '', w: 10, apply: (l) => { l.flags.oyaBond = (l.flags.oyaBond || 0) - 0.5; return '電話に出られず、かけ直すのも忘れてしまいました。'; } }
