  const HOBBY_Y = { '海外旅行': 1970, 'ドライブ': 1965, 'カラオケ': 1977, 'ゲーム': 1983, 'アニメ・マンガ': 1963, '音楽ライブ・フェス': 1997, '推し活': 2010, '筋トレ・ジム': 1982, 'ジョギング・マラソン': 1976, 'キャンプ': 1970, 'サウナ・温泉': 1960, '写真': 1958, 'SNS・動画投稿': 2005, 'ダンス': 1990, 'ボランティア': 1995, 'サッカー観戦': 1993, 'ゴルフ': 1960, 'ペット': 1955, '資格・語学の勉強': 1960, '手芸・ハンドメイド': 1950, '国内旅行': 1955, '映画鑑賞': 0, '鉄道': 1960, 'プロ野球観戦': 1950, 'ウォーキング': 1990, '登山': 1955 };
