    const opts = pick.map((h) => ({ label: h[0], hint: `参加人口 約${h[1].toLocaleString()}万人${h[6] ? `・年に約${h[6]}万円` : ''}`, w: w(h), apply: (l) => { l.hobbies = (l.hobbies || []).concat([h[0]]).slice(-3); return `${h[0]}が趣味になりました。`; } }));
    opts.push({ label: 'とくに趣味はない', hint: '仕事や家のことで手一杯', w: opts.reduce((t, o) => t + o.w, 0) * 0.15, apply: () => 'とくに趣味と呼べるものはありません。' });
    return opts;
